from concurrent.futures import ThreadPoolExecutor

import pytest

MAX_WORKERS: int = 4
"""Number of threads sum_squares uses; read at call time."""


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int]) -> int:
    """Sum of x*x over every element of xs, with the squares computed in
    parallel on a thread pool of MAX_WORKERS threads.

    The result is identical for every worker count. An empty list gives 0.
    xs is not modified.
    """
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=max(1, MAX_WORKERS)) as ex:
        squares = list(ex.map(square, xs))
    return sum(squares)


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_big_ints_no_overflow() -> None:
    big = 10**20
    assert sum_squares([big, big]) == 2 * big * big


def test_input_not_mutated() -> None:
    xs = [3, -1, 2]
    sum_squares(xs)
    assert xs == [3, -1, 2]


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 32])
def test_same_result_at_every_worker_count(
    monkeypatch: pytest.MonkeyPatch, workers: int
) -> None:
    monkeypatch.setitem(globals(), "MAX_WORKERS", workers)
    xs = list(range(-50, 200))
    expected = sum(x * x for x in xs)
    assert sum_squares(xs) == expected


@pytest.mark.parametrize("workers", [1, 2, 8, 64])
def test_fewer_items_than_workers(
    monkeypatch: pytest.MonkeyPatch, workers: int
) -> None:
    monkeypatch.setitem(globals(), "MAX_WORKERS", workers)
    assert sum_squares([]) == 0
    assert sum_squares([5]) == 25
    assert sum_squares([1, 2]) == 5


def test_large_list_matches_sequential() -> None:
    xs = [(i * 7919) % 1009 - 500 for i in range(5000)]
    assert sum_squares(xs) == sum(square(x) for x in xs)


def test_repeatable() -> None:
    xs = list(range(1000))
    results = {sum_squares(xs) for _ in range(5)}
    assert results == {sum(x * x for x in xs)}


def test_uses_thread_pool_type_available() -> None:
    # Sanity check that the executor the task calls for is importable.
    with ThreadPoolExecutor(max_workers=1) as ex:
        assert ex.submit(square, 4).result() == 16

